<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Categories"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php $cats=admin_data('categories.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=post_str('name');if($name&&!in_array($name,$cats,true))$cats[]=$name;admin_save('categories.json',array_values($cats));flash('success','Category saved.');redirect_admin('categories.php');}if(isset($_GET['delete'])){if(!hash_equals(csrf(),$_GET['csrf']??''))die('Invalid request');$cats=array_values(array_filter($cats,fn($c)=>$c!==(string)$_GET['delete']));admin_save('categories.json',$cats);flash('success','Category deleted.');redirect_admin('categories.php');}?><div class="row"><div class="col-md-5"><div class="card"><div class="card-header"><h3 class="card-title">Add Category</h3></div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="form-group"><label>Category Name</label><input class="form-control" name="name" required></div><button class="btn btn-pink">Add Category</button></form></div></div></div><div class="col-md-7"><div class="card"><div class="card-header"><h3 class="card-title">Categories</h3></div><div class="card-body"><div class="row"><?php foreach($cats as $c):?><div class="col-sm-6 mb-2"><div class="border rounded p-2 d-flex justify-content-between align-items-center"><b><?=h($c)?></b><a class="text-danger" href="categories.php?delete=<?=urlencode($c)?>&csrf=<?=h(csrf())?>" onclick="return confirm('Delete category?')"><i class="fas fa-trash"></i></a></div></div><?php endforeach;?></div></div></div></div></div></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>